 	#[verifier::external_body]
 pub proof fn temp_pred_equality<T>(p: TempPred<T>, q: TempPred<T>)
     requires
         p.entails(q),
         q.entails(p),
     ensures p == q,
 	{
 		unimplemented!()
 	}

 pub proof fn always_and_equality<T>(p: TempPred<T>, q: TempPred<T>)
     ensures always(p.and(q)) == always(p).and(always(q)),
 {
     // Unfold definitions of `always` and `and`.
     // This is purely a spec-level equality of `TempPred` values.
     assert(always(p.and(q)) == always(p).and(always(q)) by {
         // Both sides are `TempPred::new` with equivalent predicate bodies.
         // Reduce to extensional equality of the `spec_fn` field.
         //
         // `always(r).satisfied_by(ex)` is `forall i. r.satisfied_by(ex.suffix(i))`.
         // `always(p).and(always(q)).satisfied_by(ex)` is
         // `forall i. p(ex.suffix(i))  &&  forall i. q(ex.suffix(i))`.
         // Rewriting yields the same as `forall i. p(ex.suffix(i)) && q(ex.suffix(i))`.
         //
         // We can finish by propositional reasoning over `forall`.
         forall |ex: Execution<T>| {
             // Evaluate both sides' satisfied predicates.
             // (We use the extensionality of `TempPred`.)
             assert(
                 always(p.and(q)).satisfied_by(ex)
                     == always(p).and(always(q)).satisfied_by(ex)
             )
         }
     });
 }


 }

