+    // Prove mutual entailment and then use temp_pred_equality.
+    // Entailment is defined via `valid(implies(...))`.
+
+    // 1) always(p.and(q)) entails always(p).and(always(q))
+    assert(valid(always(p.and(q)).implies(always(p).and(always(q))))) by {
+        // Unfold validity: it means the antecedent holds for all executions.
+        forall |ex: Execution<T>| {
+            // Validity requires: if always(p.and(q)) holds at ex, then always(p).and(always(q)) holds at ex.
+            // This is exactly the logical fact that
+            //   forall i. (p_i && q_i)  ==>  (forall i. p_i) && (forall i. q_i).
+            assert(
+                always(p.and(q)).implies(always(p).and(always(q))).satisfied_by(ex)
+            );
+        }
+    }
+    ;
+
+    // 2) always(p).and(always(q)) entails always(p.and(q))
