+        forall |ex: Execution<T>| {
+            assert(
+                always(p).and(always(q)).implies(always(p.and(q))).satisfied_by(ex)
+            );
+        }
+    }
+    ;
+
+    temp_pred_equality(
+        always(p.and(q)),
+        always(p).and(always(q)),
+    );
